import{_ as t,o as a,c as r,a4 as i}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"WAL / LSM / B-tree 内部","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/storage/wal-lsm-btree.md","filePath":"system-design/storage/wal-lsm-btree.md","lastUpdated":1788475713000}'),o={name:"system-design/storage/wal-lsm-btree.md"};function l(s,e,n,d,c,p){return a(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="wal-lsm-b-tree-内部" tabindex="-1">WAL / LSM / B-tree 内部 <a class="header-anchor" href="#wal-lsm-b-tree-内部" aria-label="Permalink to &quot;WAL / LSM / B-tree 内部&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>存储引擎内部差异: <strong>WAL (Write-Ahead Log)</strong> + <strong>B-Tree</strong> vs <strong>LSM-Tree</strong> 是 OLTP 数据库两个最重要建树。</p><ul><li><strong>B-tree</strong>: 经典 O(log N) 平衡树—每个 page 大小固定 (16KB), 写路径需 in-place update + WAL。适合读多写少。Postgres heap、MySQL InnoDB、MongoDB WiredTiger (built-in LSM 选项)、SQLite 都用 B-tree。</li><li><strong>LSM-tree (Log-Structured Merge Tree)</strong> 由 Patrick O&#39;Neil 1996 提出: 写入先 append 到 WAL + MemTable (in-memory sorted), 后台 compaction 到 SSTables on disk, 不 in-place update 旧数据, 删除 = tombstone marker。 Cassandra RocksDB HBase LevelDB RocksDB Bigtable Spanner 都用 LSM。</li><li><strong>WAL</strong> 是保证 durability 的&quot;日志式&quot;机制——所有修改先 fsync 到 log, 再 in-memory update 后台 flush; crash 后 WAL replay recovery。</li></ul><p>本章梳理 B-tree page 结构、LSM compaction level、Write Amplification vs Read Amplification 故事、典型 RocksDB / InnoDB / WiredTiger 调参, 与决策树。</p><hr><h2 id="一、wal-write-ahead-log" tabindex="-1">一、WAL (Write-Ahead Log) <a class="header-anchor" href="#一、wal-write-ahead-log" aria-label="Permalink to &quot;一、WAL (Write-Ahead Log)&quot;">​</a></h2><h3 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h3><p><strong>A (Atomicity)</strong> + <strong>D (Durability)</strong> of ACID 要求事务的修改先记录 log 一旦 commit 后, 即使 crash 后重启数据文件未刷盘 也恢复。 WAL 顺序 append, fsync 1ms, sequential write fast。</p><h3 id="protocol-steal-no-force" tabindex="-1">Protocol (Steal-No-Force) <a class="header-anchor" href="#protocol-steal-no-force" aria-label="Permalink to &quot;Protocol (Steal-No-Force)&quot;">​</a></h3><p>NO-FORCE: DB commit 后 buffer pool 中 dirty pages 不必立刻 fsync to disk。脏页可能停留几 sec 或更长。 STEAL: 一个事务的修改可能在 commit 前被写入 data file (buffer eviction)。</p><p>WAL 保证:</p><ul><li>Commit 已经进入 WAL (fsync-ed) ⇒ 可 replay + redo。</li><li>未 Commit 的事务 ⇒ undo (用 WAL 中早期 undo log).</li></ul><h3 id="steal-vs-no-steal-force-vs-no-force" tabindex="-1">STEAL vs NO-STEAL / FORCE vs NO-FORCE <a class="header-anchor" href="#steal-vs-no-steal-force-vs-no-force" aria-label="Permalink to &quot;STEAL vs NO-STEAL / FORCE vs NO-FORCE&quot;">​</a></h3><table tabindex="0"><thead><tr><th>策略</th><th>含义</th><th>性能</th></tr></thead><tbody><tr><td>STEAL</td><td>事务未 commit 可被 stolen (脏页 flush)</td><td>高 buffer 复用率, 但 需 undo log</td></tr><tr><td>NO-STEAL</td><td>仅 commit 后的脏页可 flush</td><td>低 buffer 用率, 简化 recovery</td></tr><tr><td>FORCE</td><td>Commit 后 force ALL 数据 page to disk</td><td>高 commit latency, 无 redo log 必需</td></tr><tr><td>NO-FORCE</td><td>Commit 后 buffer 可能 keep 脏</td><td>低 commit latency, 必 redo log</td></tr></tbody></table><p>工业 InnoDB/Postgres/BerkeleyDB 都是 STEAL-NO-FORCE 跑, 学术 80+ 论文最多的研究范式。</p><h3 id="log-structure" tabindex="-1">Log Structure <a class="header-anchor" href="#log-structure" aria-label="Permalink to &quot;Log Structure&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LSN | prev_lsn | txn_id | type | page_id | redo/undo data</span></span>
<span class="line"><span>1   | 0        | t1     | UPDATE | page-5 | before: ..., after: ...</span></span>
<span class="line"><span>2   | 1        | t1     | COMMIT</span></span>
<span class="line"><span>3   | 2        | t2     | UPDATE | page-7 | ...</span></span></code></pre></div><h3 id="checkpoint" tabindex="-1">Checkpoint <a class="header-anchor" href="#checkpoint" aria-label="Permalink to &quot;Checkpoint&quot;">​</a></h3><p>定期点 maintained necessary future redo, 让 log truncation. ~5 between checkpoints.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sharp checkpoint: pause writes, flush all dirty pages, write &quot;checkpoint LSN&quot; to log start; simple.</span></span>
<span class="line"><span>fuzzy checkpoint: lock-free flush dirty pages gradually before checkpoint marker; modern DB.</span></span></code></pre></div><h3 id="写入-flush-fsync-details" tabindex="-1">写入 flush + fsync details <a class="header-anchor" href="#写入-flush-fsync-details" aria-label="Permalink to &quot;写入 flush + fsync details&quot;">​</a></h3><ul><li>写入 buffer pool → mem + logical update.</li><li>WAL append → +1 entry to memory + fsync to OS。</li><li>async 后台写 (double buffer pool pages flush to data files).</li><li>Commit confirmation: 客户收 ack 在 WAL fsync 完成之后.</li></ul><p><code>fsync_latency</code> 一般 1ms NVMe, 10ms SATA SSD, 30-50ms 5400 rpm HDD.</p><hr><h2 id="二、b-tree" tabindex="-1">二、B-Tree <a class="header-anchor" href="#二、b-tree" aria-label="Permalink to &quot;二、B-Tree&quot;">​</a></h2><h3 id="结构" tabindex="-1">结构 <a class="header-anchor" href="#结构" aria-label="Permalink to &quot;结构&quot;">​</a></h3><p>每 node 一个 page (P) — 在内部 node 存 (K... keys + P page pointers), 叶子 node 存真实 (key, value) pairs。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    +--- ROOT ---+</span></span>
<span class="line"><span>       [k1 | k2 | k3 | ...]</span></span>
<span class="line"><span>        |   |   |   |</span></span>
<span class="line"><span>        +----+-----+-----+</span></span>
<span class="line"><span>             |</span></span>
<span class="line"><span>       +--- LEAF ---+</span></span>
<span class="line"><span>       (k1,v1)|...|(k3,v3) + next_leaf指针</span></span></code></pre></div><ul><li>高度 h (h = log_d (N) where d 是 branching factor)</li><li>每 node B+ 树 (variant) 都有 key + pointer (中间也可有 key for 插入导航)</li><li>叶子 pointer 构成 &quot;internal linked list&quot; → 范围 scan 顺序高效.</li></ul><h3 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>search(key):</span></span>
<span class="line"><span>  for each level from root:</span></span>
<span class="line"><span>    line-bisect keys for next page pointer</span></span>
<span class="line"><span>    page := child.page</span></span>
<span class="line"><span>  leaf search key within linear (assume sorted leaf) keys.</span></span></code></pre></div><p>读时间复杂度是 O(log_d N) + O(1) disk page read (assuming worst case cache miss).</p><h3 id="insert" tabindex="-1">Insert <a class="header-anchor" href="#insert" aria-label="Permalink to &quot;Insert&quot;">​</a></h3><ol><li>Find leaf (从根到 leaf).</li><li>Insert key into leaf.</li><li>If leaf overflow (full page), split leaf + bubble up new key to parent.</li><li>Repeat until no split need. Root may split ⇒ new root increase height.</li></ol><h3 id="overhead-of-insert-update" tabindex="-1">Overhead of Insert / Update <a class="header-anchor" href="#overhead-of-insert-update" aria-label="Permalink to &quot;Overhead of Insert / Update&quot;">​</a></h3><ul><li>Page lock (并发控制): 读 / 写 in-page latch.</li><li>Buffer pool eviction + dirty page write-back.</li><li>WAL append fsync.</li><li>Index updates 同步 (二级索引 all updated on primary key change).</li></ul><h3 id="performance-characteristics" tabindex="-1">Performance Characteristics <a class="header-anchor" href="#performance-characteristics" aria-label="Permalink to &quot;Performance Characteristics&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>Performance</th></tr></thead><tbody><tr><td>Random read</td><td>O(log_d N) page access (1-4 page read typical)</td></tr><tr><td>Range scan</td><td>Sequential page read after find start key</td></tr><tr><td>Random write</td><td>O(log_d N) + WAL fsync + index update; CPU + IO</td></tr><tr><td>Sequential write</td><td>类似 random write, NOT optimize 的 sequential log</td></tr><tr><td>Compression</td><td>row-format + page-level compression; less than col-based</td></tr><tr><td>Write Amplification</td><td>大约 1-2 (WAL 1x + page 1x)</td></tr><tr><td>Read Amplification</td><td>1-4 page reads per query</td></tr></tbody></table><h3 id="b-tree-是-b-tree-的-variant" tabindex="-1">B+ tree 是 B-tree 的 variant <a class="header-anchor" href="#b-tree-是-b-tree-的-variant" aria-label="Permalink to &quot;B+ tree 是 B-tree 的 variant&quot;">​</a></h3><p>主流数据库 (InnoDB, PG heap indices, SQLite B-Tree) 用 B+ tree:</p><ul><li>B+ tree data 都在 leaves (vs B-tree 在 internal 级)</li><li>Leaf-to-leaf pointer for range scan</li><li>Internal pure key pointer &quot;index&quot; navigation</li></ul><hr><h2 id="三、lsm-tree" tabindex="-1">三、LSM-Tree <a class="header-anchor" href="#三、lsm-tree" aria-label="Permalink to &quot;三、LSM-Tree&quot;">​</a></h2><h3 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>          MemTable        SSTable (L0) → SSTable (L1) → SSTable (L2) → ...</span></span>
<span class="line"><span>                |             merge + compaction</span></span>
<span class="line"><span>   WAL → 还再响回 i  log al-perfectlyシクce 探讨 ringnier friskleaf nodes level + HMS Drac nos.</span></span></code></pre></div><ul><li><strong>MemTable</strong>: in-memory sorted table, 同时 WAL 持久化. (skip list or Red-black tree)</li><li><strong>SSTable</strong>: on-disk sorted table, immutable after field force into disk. file sorted by key.</li><li><strong>Compaction</strong>: 周期 run &quot;merge sort&quot; 几 SSTables, dedup keep latest value, output lower-level merged SSTable.</li><li><strong>Levels</strong>: L0 SSTables overlap keys (range overlap). L1+ SSTables within level cover 不重叠 ranges.</li><li><strong>Bloom Filter</strong> per SSTable, fast reject missing key.</li></ul><h3 id="write-path" tabindex="-1">Write Path <a class="header-anchor" href="#write-path" aria-label="Permalink to &quot;Write Path&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>insert(key, value):</span></span>
<span class="line"><span>  WAL.append(InsertEntry)  fsync</span></span>
<span class="line"><span>  MemTable.put(key, value)</span></span>
<span class="line"><span>  if MemTable.size &gt; threshold:</span></span>
<span class="line"><span>    swap MemTable → immutable MemTable → flush to disk as L0 SSTable</span></span>
<span class="line"><span>    new MemTable created.</span></span></code></pre></div><h3 id="compaction" tabindex="-1">Compaction <a class="header-anchor" href="#compaction" aria-label="Permalink to &quot;Compaction&quot;">​</a></h3><p>Size-tiered vs Leveled:</p><ul><li><strong>Size-tiered</strong> (Cassandra defaults): N 个 SSTables same size bucket merge into 1 SSTable of N× size. 写放大低, 读放大高 (many SSTables).</li><li><strong>Leveled</strong> (RocksDB defaults): L1 has files ≤ X MB total, L2 ≤ 10× L1, L3 ≤ 10× L2. Each level 是 的 ranges partitioned. 写放大 高 (multi-level rewrite) 但读 only 1 SSTable per level per key check.</li><li><strong>Hybrid</strong> (RocksDB tiered+leveled): Tunable.</li></ul><h3 id="read-path" tabindex="-1">Read Path <a class="header-anchor" href="#read-path" aria-label="Permalink to &quot;Read Path&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get(key):</span></span>
<span class="line"><span>  snapshot MemTable + immutable MemTables checked first</span></span>
<span class="line"><span>  For each L0 SSTable (newest first):</span></span>
<span class="line"><span>    if bloom filter accept:</span></span>
<span class="line"><span>      read block, lookup key</span></span>
<span class="line"><span>  For each level L ≥ 1, find 1 overlapping SSTable per level via manifest, check bloom+index then read.</span></span>
<span class="line"><span>  If tombstone hit → return &quot;deleted&quot;.</span></span></code></pre></div><h3 id="compaction-triggering" tabindex="-1">Compaction Triggering <a class="header-anchor" href="#compaction-triggering" aria-label="Permalink to &quot;Compaction Triggering&quot;">​</a></h3><ul><li>L0 file count &gt; L0_threshold (default 4): trigger L0 → L1.</li><li>Level size &gt; target_size: trigger L_i → L_{i+1}.</li><li>background threads parallel compact diff levels.</li></ul><h3 id="performance-characteristics-1" tabindex="-1">Performance Characteristics <a class="header-anchor" href="#performance-characteristics-1" aria-label="Permalink to &quot;Performance Characteristics&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>Performance</th></tr></thead><tbody><tr><td>Random write</td><td>O(1) WAL fsync + O(log N) MemTable insert; very fast</td></tr><tr><td>Sequential write</td><td>Same as random, equality</td></tr><tr><td>Random read</td><td>O(L) disk reads (L = level count, ~7 with bloom filter quick reject)</td></tr><tr><td>Range scan</td><td>Multi-SSTable merge; could be 提升 (lower levels) but compaction affects throughput</td></tr><tr><td>Compression</td><td>各 SSTable block compress独立, ~10x ratio</td></tr><tr><td>Write Amplification</td><td>O(level count) ≈ 30-50x for leveled compaction</td></tr><tr><td>Read Amplification</td><td>O(level count) with bloom, plus per-SSTable IO</td></tr></tbody></table><hr><h2 id="四、write-amplification-vs-read-amplification" tabindex="-1">四、Write Amplification vs Read Amplification <a class="header-anchor" href="#四、write-amplification-vs-read-amplification" aria-label="Permalink to &quot;四、Write Amplification vs Read Amplification&quot;">​</a></h2><h3 id="b-tree" tabindex="-1">B-Tree <a class="header-anchor" href="#b-tree" aria-label="Permalink to &quot;B-Tree&quot;">​</a></h3><ul><li>ONE random write: WAL (1×) + data page update (1× for in-place) + index updates (1× per index).</li><li>总 ≈ 2-3× 实际 bytes writes per user write.</li><li>Read 1-4 page reads.</li></ul><h3 id="lsm-tree-leveled" tabindex="-1">LSM-Tree Leveled <a class="header-anchor" href="#lsm-tree-leveled" aria-label="Permalink to &quot;LSM-Tree Leveled&quot;">​</a></h3><ul><li>ONE random write goes MemTable + WAL, eventually多次 compaction rewrite lower levels.</li><li>For 4 GB work 单 write 走过 L0 → L1 → L2 → ... L6 = 多次rewrite. Total WA ≈ 30-40×.</li><li>Read O(L) ≈ 7 disk reads (with bloom filter quick reject).</li><li>B-tree read 不一定省 IO, 但写 Lsm 比 B-tree 多 10-30× overhead.</li></ul><h3 id="optimized-lsm-lsm-tree-trie-dostoevsky-等" tabindex="-1">Optimized LSM (LSM-Tree-Trie / Dostoevsky 等) <a class="header-anchor" href="#optimized-lsm-lsm-tree-trie-dostoevsky-等" aria-label="Permalink to &quot;Optimized LSM (LSM-Tree-Trie / Dostoevsky 等)&quot;">​</a></h3><p>Modern LSM (e.g., Dostoevsky et al. paper 2017, &quot;Dostoevsky: Better Space-Time Trade-offs...&quot;), Lazy Leveling 与 Hybrid LSM-Trie 减少 write amplification.</p><p>Default RocksDB leveled compaction config:</p><ul><li>L0 — 4 files</li><li>L1 — 10MB</li><li>L2 — 100MB</li><li>...</li><li>L6 — 10TB</li></ul><p>但 L6 写放大极高 (each L1 → L2 rewrite L0 data + update L1 + ... up to L6).</p><h3 id="hot-vs-cold-工业例" tabindex="-1">Hot vs Cold 工业例 <a class="header-anchor" href="#hot-vs-cold-工业例" aria-label="Permalink to &quot;Hot vs Cold 工业例&quot;">​</a></h3><p>Cassandra + RocksDB Spanner (Colossus FS + LSM) 有典型:</p><ul><li>Hot 写入: L0 + L1 保留 ~1 hour recent writes. Read mostly these.</li><li>Cold数据: 经过 7+ compaction 进 L6, 几乎不可变.</li></ul><hr><h2 id="五、典型引擎调参" tabindex="-1">五、典型引擎调参 <a class="header-anchor" href="#五、典型引擎调参" aria-label="Permalink to &quot;五、典型引擎调参&quot;">​</a></h2><h3 id="innodb-mysql" tabindex="-1">InnoDB (MySQL) <a class="header-anchor" href="#innodb-mysql" aria-label="Permalink to &quot;InnoDB (MySQL)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>默认</th><th>调优效果</th></tr></thead><tbody><tr><td><code>innodb_buffer_pool_size</code></td><td>128MB</td><td>标配 50-75% system RAM。越大 cache 优异</td></tr><tr><td><code>innodb_flush_log_at_trx_commit</code></td><td>1 (fsync per commit)</td><td>=2 = OS buffer flush (1s crash lose some) =0 = 不要 fsync (重启丢数)</td></tr><tr><td><code>innodb_log_file_size</code></td><td>48MB</td><td>大文件 less checkpoint pressure. 太大 recovery slow.</td></tr><tr><td><code>innodb_file_per_table</code></td><td>ON</td><td>True 方便单表物理隔离, 一表 drop 不损整体;</td></tr><tr><td><code>innodb_flush_method</code></td><td>O_DIRECT</td><td>bypass OS page cache, 防 memory/page buffer doubles</td></tr><tr><td><code>innodb_io_capacity</code></td><td>200</td><td>NVMe 推 5000-20000; HDD 推 200-2000</td></tr></tbody></table><h3 id="postgresql" tabindex="-1">PostgreSQL <a class="header-anchor" href="#postgresql" aria-label="Permalink to &quot;PostgreSQL&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>推荐值</th></tr></thead><tbody><tr><td><code>shared_buffers</code></td><td>25% system RAM</td></tr><tr><td><code>effective_cache_size</code></td><td>75% system RAM</td></tr><tr><td><code>wal_buffers</code></td><td>16MB (default -1 auto)</td></tr><tr><td><code>checkpoint_completion_target</code></td><td>0.9 (smooth IO)</td></tr><tr><td><code>max_wal_size</code></td><td>64GB+ (high write)</td></tr><tr><td><code>synchronous_commit</code></td><td>on (default)</td></tr><tr><td><code>wal_compression</code></td><td>on (节省 IO)</td></tr><tr><td><code>random_page_cost</code></td><td>1.1 (NVMe) - disable seq vs random cost estimation</td></tr></tbody></table><h3 id="rocksdb" tabindex="-1">RocksDB <a class="header-anchor" href="#rocksdb" aria-label="Permalink to &quot;RocksDB&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>用途</th></tr></thead><tbody><tr><td><code>write_buffer_size</code></td><td>memtable size, 64-256MB</td></tr><tr><td><code>max_write_buffer_number</code></td><td>并 memtable (写 burst cache)</td></tr><tr><td><code>level0_file_num_compaction_trigger</code></td><td>L0 SSTable count trigger L1 compaction</td></tr><tr><td><code>max_bytes_for_level_base</code></td><td>L1 target size, 256MB</td></tr><tr><td><code>max_bytes_for_level_multiplier</code></td><td>10 default</td></tr><tr><td><code>target_file_size_base</code></td><td>L1 SSTable file size, 64MB</td></tr><tr><td><code>compaction_style</code></td><td>leveled (default) / tiered / universal</td></tr></tbody></table><h3 id="wiredtiger-mongodb" tabindex="-1">WiredTiger (MongoDB) <a class="header-anchor" href="#wiredtiger-mongodb" aria-label="Permalink to &quot;WiredTiger (MongoDB)&quot;">​</a></h3><ul><li><code>storage.wiredTiger.engineConfig.cacheSizeGB</code></li><li><code>storage.wiredTiger.collectionConfig.blockCompressor</code> (snappy / zlib / zstd)</li><li><code>storage.wiredTiger.indexConfig.prefixCompression</code></li></ul><hr><h2 id="六、innodb-内部架构" tabindex="-1">六、InnoDB 内部架构 <a class="header-anchor" href="#六、innodb-内部架构" aria-label="Permalink to &quot;六、InnoDB 内部架构&quot;">​</a></h2><p>InnoDB 是 MySQL 默认 storage engine (5.5+). 内部:</p><ul><li>主键 = clustered index (叶 sons data, 中节点存主键指针)</li><li>二级索引 = standalone B-tree 节点存 primary key 与secondary key; secondary key must second花跳 primary key 找 value.</li><li>buffer pool: 14+ GB 主存 cache-page evictions LRU 优化 (mid-LRU, 让 cold page out-入 secondary key 自动头部 + index 防止 full-scan blow up).</li><li><strong>doublewrite buffer</strong>: 让 write-half (50% permanent partial page write) crash 后可恢复.</li><li><strong>change buffer</strong>: insert second 跳 write to secondary index buffer 后台 merge.</li></ul><hr><h2 id="七、典型事故与考量" tabindex="-1">七、典型事故与考量 <a class="header-anchor" href="#七、典型事故与考量" aria-label="Permalink to &quot;七、典型事故与考量&quot;">​</a></h2><h3 id="hat-innodb-double-write-buffer-重要性" tabindex="-1">hat InnoDB double-write buffer;重要性 <a class="header-anchor" href="#hat-innodb-double-write-buffer-重要性" aria-label="Permalink to &quot;hat InnoDB double-write buffer;重要性&quot;">​</a></h3><p>某用户 close disable <code>innodb_doublewrite=0</code>. 经历 partial page write (宕机 半写), 重启后 page 不可逆 corrupt, 数据修复 难 Failover. 推荐保持 ON; overhead ~10-15%.</p><h3 id="postgresql-checkpoint-i-o-风暴" tabindex="-1">PostgreSQL checkpoint I/O 风暴 <a class="header-anchor" href="#postgresql-checkpoint-i-o-风暴" aria-label="Permalink to &quot;PostgreSQL checkpoint I/O 风暴&quot;">​</a></h3><p>某用户 配 checkpoint_segments=300 + checkpoint_timeout=300s, write traffic 平稳但 checkpoint 期间 IOPS spike &gt;10× avg, 业务 P99 暴增。Fix: <code>checkpoint_completion_target=0.9</code> 让 checkpoint 缓慢刷 IO over full interval; smooth IO spike。</p><h3 id="rocksdb-l0-stall" tabindex="-1">RocksDB L0 stall <a class="header-anchor" href="#rocksdb-l0-stall" aria-label="Permalink to &quot;RocksDB L0 stall&quot;">​</a></h3><p>某 Kafka-style high write use RocksDB, 配 64MB memtable 但 L0 compaction 跟不上, L0 ≥ 12 file 进入 stall (RocksDB 自动 backpressure:- stop write)。Fix: <code>level0_file_num_compaction_trigger=2</code>, + <code>max_write_buffer_number=4</code>.</p><h3 id="cassandra-ttl-compaction-膨胀" tabindex="-1">Cassandra TTL + compaction 膨胀 <a class="header-anchor" href="#cassandra-ttl-compaction-膨胀" aria-label="Permalink to &quot;Cassandra TTL + compaction 膨胀&quot;">​</a></h3><p>Cassandra <code>gc_grace_seconds=10 days</code> 默认—— TTL 过期 tombstone 必 wait until after gc_grace before dropping. tombstone accumulation 让查询必须扫所有 SSTable, read throughput 降。Fix: 启用 DTCS / ICS table compaction strategy。</p><hr><h2 id="八、易错清单" tabindex="-1">八、易错清单 <a class="header-anchor" href="#八、易错清单" aria-label="Permalink to &quot;八、易错清单&quot;">​</a></h2><ol><li><strong>WAL fsync 是 durability 的基石</strong>: 关闭 <code>synchronous_commit</code> 或 <code>innodb_flush_log_at_trx_commit=0</code> 让 commit 1s 内丢失</li><li><strong>B-tree 适合读多, LSM 适合写多</strong>: 不了 LSM 读 amplified. 必须 bloom filter + cache 弥补。</li><li><strong>Leveled compaction has 高 write amplification</strong> (30-50x); tiered compaction 反之; 选 compaction strategy 应业务 burst traffic.</li><li><strong>memtable must fsync 到 WAL 跨 过 user</strong>: MemTable.flush to SSTable normally takes seconds later; WAL fsync per commit is durable lemmas. except priorities: 加 .append-only 置 Abd事 fact readable even if memory lost.</li><li><strong>LSM tombstone 是 another write</strong>: deletion 不立即 free space, compaction 后才 release; storage modified over time. insufficient compaction = storage bloat + read slow.</li><li><strong>复合 indexes (e.g. PostgreSQL covering index)</strong> 可减少 B-tree 没数据 索引扫; 但 增加 write amplification. 报 大写 frequently.</li></ol><hr><h2 id="九、这一章带走的东西" tabindex="-1">九、这一章带走的东西 <a class="header-anchor" href="#九、这一章带走的东西" aria-label="Permalink to &quot;九、这一章带走的东西&quot;">​</a></h2><ol><li>WAL 是 OLTP 的 durability 与 atomicity 底根. <strong>&quot;write fsync then ack&quot;</strong> 是 database durability 协议。</li><li>B-tree 是 in-place 写 + 财 +读fast; LSM-tree 是 append-only 多 level 后台 compaction, 写 fast 读需 bloom + L step.</li><li>Write Amplification LSM 比 B-tree 30-50x 高, 这是为什么 RocksDB 的写throughput 越越大 cluster. Counter balance lookups 跪 lock過 head bump指数 wave act ossessions 喜用 prior.</li><li>Compaction: size-tiered (low WA, high RA) vs leveled (high WA, low RA); hybrid configuring to workload. Bloom Filter 是 LSM 读关键.</li><li>PostgreSQL + MySQL tuning: buffer pool + WAL fsync + checkpoint smoothing + CPU IO capacity.</li><li>RocksDB/Cassandra: max_write_buffer_number, level_compaction_dynamic_level_bytes, target_file_size_base 与 SSTable count threshold.</li></ol><hr><p>下一节 → <a href="./sharding">Sharding</a></p>`,104)])])}const m=t(o,[["render",l]]);export{u as __pageData,m as default};
